\version "2.27.2"
% automatically converted by musicxml2ly from 11b-TimeSignatures-NoTime.xml
\pointAndClickOff

\header {
  texidoc = "A score without a time signature at the beginning (but with <key>
    and <clef> elements). The second bar sets a 2/2 time signature with
    ‘print-object=\"no\"’ for both staves, and the third bar sets a 4/4 time
    signature with ‘print-object=\"no\"’ only for the lower staff.

    Whether a time signature is actually displayed at the very beginning (if
    there is no <time> element) is application-dependent."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative f' {
  \clef "treble" \key c \major \once \omit Staff.TimeSignature f1 | % 1
  \once \omit Staff.TimeSignature \time 2/2 f1 | % 2
  \numericTimeSignature \time 4/4 f1 }

PartPOneVoiceTwo = \relative b, {
  \clef "bass" \key c \major \once \omit Staff.TimeSignature b1 | % 1
  \once \omit Staff.TimeSignature \time 2/2 b1 | % 2
  \once \omit Staff.TimeSignature \time 4/4 b1 }


% The score definition
\score {
  <<
    \new PianoStaff = "P1" <<
      \context Staff = "1" <<
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
      \context Staff = "2" <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceTwo" {
          \PartPOneVoiceTwo
        }
      >>
    >>
  >>
  \layout {}
